  a.blt b =
    if (decide (a.num < 0) && decide (0 ≤ b.num)) = true then true
    else
      if a.num = 0 then decide (0 < b.num)
      else if (decide (0 < a.num) && decide (b.num ≤ 0)) = true then false else decide (a.num * ↑b.den < b.num * ↑a.den)

