∀ {α : Type u_1} {β : Type u_2} {inst : PseudoEMetricSpace α} {inst_1 : PseudoEMetricSpace β} {toFun : α → β}
  {edist_eq' : ∃ r, r ≠ 0 ∧ ∀ (x y : α), edist (toFun x) (toFun y) = ↑r * edist x y} {toFun_1 : α → β}
  {edist_eq'_1 : ∃ r, r ≠ 0 ∧ ∀ (x y : α), edist (toFun_1 x) (toFun_1 y) = ↑r * edist x y},
  { toFun := toFun, edist_eq' := edist_eq' } = { toFun := toFun_1, edist_eq' := edist_eq'_1 } → toFun = toFun_1

