  [inst_3 : Semiring A] [inst_4 : Module A V] [inst_5 : SMul K A] [inst_6 : IsScalarTower K A V],
  Module.finrank K V = 1 → IsSimpleOrder (Submodule A V)

∀ {R : Type u_1} [inst : CommSemiring R] {A : Type u_2} [inst_1 : Semiring A] [inst_2 : Algebra R A] {A' : Type u_3}
  [inst_3 : Semiring A'] [inst_4 : Algebra R A'] (f : A →ₐ[R] A') (x1 x2 : Submodule R A),
  Submodule.map f.toLinearMap (x1 ⊔ x2) = Submodule.map f.toLinearMap x1 ⊔ Submodule.map f.toLinearMap x2

∀ {E : Type u_1} {inst : NormedAddCommGroup E} {inst_1 : NormedSpace ℝ E} {H : Type u_2} {inst_2 : TopologicalSpace H}
  {I : ModelWithCorners ℝ E H} {M : Type u_3} {inst_3 : MetricSpace M} {inst_4 : ChartedSpace H M}
  {inst_5 : IsManifold I (↑⊤) M} {inst_6 : CompactSpace M} {inst_7 : GromovCompactness.ClosedTameTarget I M} {k : ℕ}
  {u₁ u₂ : GromovCompactness.Extensions.MarkedStableMap I k} {v_equiv : u₁.tree.V ≃ u₂.tree.V}
  {adj_compat : ∀ (v w : u₁.tree.V), u₁.tree.adj.Adj v w ↔ u₂.tree.adj.Adj (v_equiv v) (v_equiv w)}
  {moeb : u₁.tree.V → GromovCompactness.MoebiusFrame}
  {node_compat :
    ∀ (v w : u₁.tree.V) (h : u₁.tree.adj.Adj v w),
      (moeb v).toHomeo (u₁.tree.node_point v w h) = u₂.tree.node_point (v_equiv v) (v_equiv w) ⋯}
  {mark_vertex_compat : ∀ (i : Fin k), v_equiv (u₁.tree.mark_vertex i) = u₂.tree.mark_vertex i}
  {mark_point_compat :
    ∀ (i : Fin k), (moeb (u₁.tree.mark_vertex i)).toHomeo (u₁.tree.mark_point i) = u₂.tree.mark_point i}
  {map_compat : ∀ (v : u₁.tree.V) (z : ↑GromovCompactness.CP1), u₂.map (v_equiv v) ((moeb v).toHomeo z) = u₁.map v z}
  {v_equiv_1 : u₁.tree.V ≃ u₂.tree.V}
  {adj_compat_1 : ∀ (v w : u₁.tree.V), u₁.tree.adj.Adj v w ↔ u₂.tree.adj.Adj (v_equiv_1 v) (v_equiv_1 w)}
  {moeb_1 : u₁.tree.V → GromovCompactness.MoebiusFrame}
  {node_compat_1 :
    ∀ (v w : u₁.tree.V) (h : u₁.tree.adj.Adj v w),
      (moeb_1 v).toHomeo (u₁.tree.node_point v w h) = u₂.tree.node_point (v_equiv_1 v) (v_equiv_1 w) ⋯}
  {mark_vertex_compat_1 : ∀ (i : Fin k), v_equiv_1 (u₁.tree.mark_vertex i) = u₂.tree.mark_vertex i}
  {mark_point_compat_1 :
    ∀ (i : Fin k), (moeb_1 (u₁.tree.mark_vertex i)).toHomeo (u₁.tree.mark_point i) = u₂.tree.mark_point i}
  {map_compat_1 :
    ∀ (v : u₁.tree.V) (z : ↑GromovCompactness.CP1), u₂.map (v_equiv_1 v) ((moeb_1 v).toHomeo z) = u₁.map v z},
  { v_equiv := v_equiv, adj_compat := adj_compat, moeb := moeb, node_compat := node_compat,
        mark_vertex_compat := mark_vertex_compat, mark_point_compat := mark_point_compat, map_compat := map_compat } =
      { v_equiv := v_equiv_1, adj_compat := adj_compat_1, moeb := moeb_1, node_compat := node_compat_1,
        mark_vertex_compat := mark_vertex_compat_1, mark_point_compat := mark_point_compat_1,
        map_compat := map_compat_1 } →
    v_equiv = v_equiv_1 ∧ moeb = moeb_1

